### How do you find the department with the widest age range?

```java
package com.bank.hr;

import java.util.*;
import java.util.stream.Collectors;

public class MostDiverseAgeRange {
    public static void main(String[] args) {
        List<Employee> employees = Employee.getSampleEmployees();

        Map<String, IntSummaryStatistics> statsByDept = employees.stream()
            .collect(Collectors.groupingBy(
                Employee::getDepartment,
                Collectors.summarizingInt(Employee::getAge)));

        Optional<Map.Entry<String, IntSummaryStatistics>> widest =
            statsByDept.entrySet().stream()
                .max(Comparator.comparingInt(
                    e -> e.getValue().getMax() - e.getValue().getMin()));

        widest.ifPresent(e -> {
            IntSummaryStatistics s = e.getValue();
            System.out.printf("%s: range = %d (min=%d, max=%d)%n",
                e.getKey(),
                s.getMax() - s.getMin(),
                s.getMin(), s.getMax());
        });
    }
}
```

